insert into public.site_settings (key, value, updated_at) values ('site', '{"namaKelas":"XI-9","jurusan":"Teknik Komputer dan Jaringan","namaSekolah":"SMK Muhammadiyah Belitang","tahunAjaran":"2026 / 2027","motto":"Solid, Kreatif, dan Berdedikasi Tanpa Batas","deskripsi":"Kelas Teknik Komputer dan Jaringan yang penuh semangat belajar, inovasi tanpa henti, dan solidaritas yang tak tergoyahkan dalam menguasai dunia teknologi digital.","sloganHero":"Komunitas pejuang digital yang siap menguasai jaringan, keamanan siber, dan teknologi masa depan dengan semangat, solidaritas, dan kompetensi nyata.","ogImage":"https://picsum.photos/seed/tkj-xi9-og/1200/630","baseUrl":"./","countdown":{"label":"Ujian Akhir Semester","target":"2026-06-10T08:00:00"},"sosmed":{"instagram":"https://instagram.com/tkj.xi9.smkn1","youtube":"https://youtube.com/@tkjxi9smkn1","tiktok":"https://www.tiktok.com/@tkjxi9smkn1"},"stats":[{"icon":"fa-users","angka":20,"suffix":"","label":"Anggota"},{"icon":"fa-trophy","angka":15,"suffix":"","label":"Prestasi"},{"icon":"fa-calendar","angka":2,"suffix":"","label":"Tahun Bersama"},{"icon":"fa-star","angka":100,"suffix":"%","label":"Semangat Belajar"}],"prestasi":[{"judul":"Juara 1 Mencintai Namun Tak Berani Mengungkapkan","tahun":"2024","tingkat":"Internasional"},{"judul":"Juara 2 Menunggu Balasan Chat yang Ternyata Cuma Typo","tahun":"2024","tingkat":"Provinsi"},{"judul":"Finalis Bertahan di Friendzone demi Lihat Dia Senyum","tahun":"2024","tingkat":"Nasional"},{"judul":"Juara 1 Spesialis Memendam Rasa Pas Liat Dia Sama yang Lain","tahun":"2024","tingkat":"Sekolah"},{"judul":"Sertifikasi Sabar Menghadapi Sikap Dingin Si Pipi Lucu","tahun":"2023","tingkat":"Nasional"}],"visi":"Menjadi kelas unggulan yang melahirkan generasi teknisi yang handal benerin koneksi internet, tapi tetap sabar menghadapi koneksi perasaan yang sering ''Request Time Out'' dari si dia.","misi":["Meningkatkan kompetensi dalam meng-unblock WhatsApp doi dan menjaga keamanan siber hati agar tidak mudah kena hack janji manis","Membangun karakter siswa yang jujur mengakui kalau dia cuma anggep teman, dan disiplin menghapus history chat yang bikin gagal move on","Mendorong budaya inovasi mencari alasan buat chat duluan dan problem solving saat chat cuma dibalas ''O'' atau ''Woke''","Memperkuat solidaritas sesama pejuang friendzone dan semangat gotong royong meminjamkan bahu saat teman kena ghosting","Mempersiapkan diri secara optimal untuk masa depan yang cerah sebagai Senior Programmer, biar nanti si dia menyesal telah berpaling"],"waliKelas":{"nama":"Bu Dina Sa''diyah","jabatan":"Wali Kelas XI-9 TKJ","foto":"https://ui-avatars.com/api/?name=Dina+Sa''diyah&background=7f1d1d&color=fff&size=200&bold=true&font-size=0.33"},"masdo":{"nama":"Masdo Officials","jabatan":"Sudah Jadi Legenda","keahlian":["Web Development","Network Administration","Digital Marketing","Content Creation"],"foto":"storage://anggota/profil-alfredo.webp"},"tkj":{"deskripsi":"Teknik Komputer dan Jaringan (TKJ) adalah program keahlian yang mempelajari instalasi, konfigurasi, pemeliharaan sistem komputer, serta perancangan dan pengelolaan jaringan komunikasi data dari skala lokal hingga enterprise.","mapel":[{"nama":"Dasar Jaringan Komputer","icon":"fa-network-wired"},{"nama":"Administrasi Server","icon":"fa-server"},{"nama":"Keamanan Jaringan","icon":"fa-shield-halved"},{"nama":"Pemrograman Web","icon":"fa-code"},{"nama":"Sistem Operasi Jaringan","icon":"fa-desktop"},{"nama":"Perakitan Komputer","icon":"fa-microchip"},{"nama":"Komunikasi Data & Fiber","icon":"fa-wifi"},{"nama":"Cloud Computing Dasar","icon":"fa-cloud"}],"karir":[{"jabatan":"Network Engineer","icon":"fa-network-wired","desc":"Merancang, mengimplementasikan, dan mengelola infrastruktur jaringan perusahaan skala enterprise."},{"jabatan":"System Administrator","icon":"fa-server","desc":"Mengelola, memelihara, dan mengoptimalkan server serta sistem operasi dalam lingkungan produksi."},{"jabatan":"Web Developer","icon":"fa-code","desc":"Membangun aplikasi dan website yang fungsional, responsif, dan berperforma tinggi."},{"jabatan":"IT Support Specialist","icon":"fa-headset","desc":"Memberikan dukungan teknis komprehensif kepada pengguna, hardware, software, dan sistem."},{"jabatan":"Cyber Security Analyst","icon":"fa-shield-halved","desc":"Menganalisis, mendeteksi, dan merespons ancaman keamanan siber dalam ekosistem digital."},{"jabatan":"Cloud Engineer","icon":"fa-cloud","desc":"Mengelola infrastruktur cloud (AWS/GCP/Azure) dan merancang solusi berbasis cloud."}],"kurikulum":[{"fase":"Kelas X","fokus":"Fondasi TKJ: perakitan hardware, instalasi OS, konsep jaringan dasar, dan pengantar pemrograman."},{"fase":"Kelas XI","fokus":"Pendalaman: administrasi jaringan enterprise, server Linux, keamanan siber, dan pengembangan web."},{"fase":"Kelas XII","fokus":"Aplikasi: proyek akhir, PKL (Praktik Kerja Lapangan), sertifikasi kompetensi, dan persiapan karir."}]},"media":{"logo_url":"storage://assets-global/logo/logo-utama.svg","audio_url":"storage://assets-global/audio/videoplayback.weba"}}'::jsonb, now())
