insert into public.guru (nama, mapel, peran, quote, expertise, urutan)
values
('Mr. Sudarto', 'TLJ & ASJ', 'System & Service Orchestrator', 'Sistem yang baik bukan yang tidak pernah down, tapi yang selalu tahu cara bangkit.', '[{"label":"Teknologi Layanan Jaringan","level":90},{"label":"Administrasi Sistem Jaringan","level":88},{"label":"Network Protocol","level":85}]'::jsonb, 0),
('Mr. Doni Suwito', 'Teknologi WAN', 'Global Connectivity Strategist', 'Jarak hanya angka. Dengan arsitektur yang benar, semua titik bisa terhubung.', '[{"label":"Wide Area Network","level":92},{"label":"Network Architecture","level":87},{"label":"Data Transmission","level":83}]'::jsonb, 1),
('Mr. Crisna', 'Pemrograman Web', 'Full-Stack Architect', 'Kode yang baik bukan yang bisa dibaca mesin, tapi yang bisa dibaca manusia.', '[{"label":"Frontend Development","level":91},{"label":"Backend & Logic","level":86},{"label":"UX & Responsivitas","level":88}]'::jsonb, 2),
('Mr. Hendri', 'AIJ & Dasar Desain Grafis', 'Infrastructure & Visual Lead', 'Infrastruktur kuat tanpa desain yang baik seperti server canggih tanpa antarmuka.', '[{"label":"Administrasi Infrastruktur","level":89},{"label":"Desain Grafis","level":82},{"label":"Visual Communication","level":80}]'::jsonb, 3),
('Mr. Deny', 'Percetakan Digital & Desain', 'Creative Output Specialist', 'Ide tanpa eksekusi hanya mimpi. Desain yang presisi adalah jembatannya.', '[{"label":"Digital Printing","level":93},{"label":"Design Precision","level":90},{"label":"Industry Standard","level":87}]'::jsonb, 4)
insert into public.skills (nama, level, icon, deskripsi, urutan)
values
('Kabel Pulling Simulator', 90, 'fa-solid fa-code-fork', 'Expert crimping kabel UTP sambil ngobrol. Pernah bikin topologi jaringan yang cuma Tuhan dan aku yang paham. Sekarang cuma Tuhan.', 0),
('Professional Googler', 80, 'fa-brands fa-meta', 'Stack Overflow adalah dokumentasi resmi. ''View Page Source'' adalah cheat code kehidupan. Ctrl+C Ctrl+V with extra steps.', 1),
('Dukun PC Bermasalah', 88, 'fa-solid fa-computer', 'Komputer mati? Coba restart. Masih mati? Ketok pelan-pelan. Berhasil? Ilmu warisan nenek moyang ini mah.', 2),
('Script Kiddie Wannabe', 75, 'fa-solid fa-repeat', 'Download tools hacking dari YouTube. Belum tau cara pake. Password sendiri sering lupa. Ironis memang.', 3),
('Terminal Cosplayer', 78, 'fa-solid fa-terminal', 'Buka terminal biar keliatan pro. Ketik ''ls'' sama ''cd'' doang. Temen kagum. Mission accomplished.', 4),
('Error Message Collector', 82, 'fa-solid fa-triangle-exclamation', 'Koleksi error message lebih banyak dari line of code. ''It works on my machine'' adalah filosofi hidup.', 5)
